import logging
import re
from urllib.parse import urlparse

from .exceptions import (NodeDetectionError, ServiceAlreadyAdded,
                         ServiceNotAvailable, ServiceNotFound,
                         UnsupportedService, WebUrlDetectionError,
                         WebUrlNotFound)
from .ssh_node import SshNode

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class NodesFactory:
    SCRIPT_PATH = '/opt/cpf/sbin/netact_status.sh'
    SUPPORTED_SERVICES = (
        'cmwas',
        'fmwas',
        'itsmwas',
        'syswas',
        'fm_pipe',
        'nwi3',
        'cls-services',
        'cls-db',
        'ne3sws'
    )
    IP_PATTERNS = {'ipv4': r'\d{1,3}(?:\.\d{1,3}){3}',
                   'ipv6': r'(?:[0-9a-fA-F]{0,4}:){1,7}[0-9a-fA-F]{0,4}'}

    def __init__(self):
        self.services = {}
        self.ssh_nodes = {}
        self._web_url = None
        self.web_username = None
        self.web_password = None

    def add_web_url(self, web_url, username, password):
        """Add Netact web user interface data."""
        self._web_url = self._parse_web_url(web_url)
        self.web_username = username
        self.web_password = password

    @property
    def web_url(self):
        if self._web_url:
            return self._web_url
        raise WebUrlNotFound('web url not found/added. Use add_web_url method first.')

    @staticmethod
    def _parse_web_url(web_url):
        web_url = web_url.strip('/')
        return urlparse(web_url).netloc or web_url

    def add_node(self, service_name, hostname, username, password):
        """Create an instance of SshNode class, establishes temporary ssh connection
        as first verification step and then checks status of given service.

        Logs warning if status is different than 'started'.
        If no exception was raised, the instance is saved and a reference to it
        by given service name is created.
        """
        if service_name in self.services.keys():
            exc_msg = f'"{service_name}" service name is already added. Use delete_node first.'
            raise ServiceAlreadyAdded(exc_msg)
        else:
            return self._add_node(service_name, hostname, username, password)

    def _add_node(self, service_name, hostname, username, password):
        if service_name in self.SUPPORTED_SERVICES:
            added = hostname in self.ssh_nodes
            ssh_connection = self.ssh_nodes[hostname] if added else SshNode(hostname, username, password)
            self._verify_node(service_name, ssh_connection)
            self.services[service_name] = hostname
            if not added:
                self.ssh_nodes[hostname] = ssh_connection
            return ssh_connection
        else:
            exc_msg = (f'"{service_name}" is not supported.\n'
                       f'Supported services: {", ".join(self.SUPPORTED_SERVICES)}')
            raise UnsupportedService(exc_msg)

    def detect_nodes(self):
        """Detect IP addresses of nodes where all supported services are running."""
        services = {}
        if self.ssh_nodes:
            with next(iter(self.ssh_nodes.values())) as ssh:
                for service_name in self.SUPPORTED_SERVICES:
                    ips = self._detect_ips(service_name, ssh)
                    services[service_name] = ips
            return services
        else:
            raise NodeDetectionError('At least one node has to be successfully added')

    def _detect_ips(self, service_name, ssh):
        ips = []
        command = f'{self.SCRIPT_PATH} status service {service_name} | awk -F":" \'{{ print $2}}\''
        hostnames = ssh.execute_command(command).stdout
        for hostname in sorted(set(hostnames.splitlines())):
            entries = ssh.execute_command(f'host {hostname}').stdout
            ip_match = re.search(self._ip_pattern(ssh.hostname), entries)
            if ip_match:
                ip = ip_match.group()
                ips.append(ip)
                logger.info(f'Detected IP address of "{service_name}" service: {ip}')
        return ips

    def detect_web_url(self):
        """Detect Netact web url."""
        if self.ssh_nodes:
            with next(iter(self.ssh_nodes.values())) as ssh:
                command = r"cat /etc/hosts | grep -E 'lbwas|ntnwas' | awk '{print $2}'"
                web_url = ssh.execute_command(command).stdout
                logger.info(f'Detected web URL: {web_url}')
                return web_url
        else:
            raise WebUrlDetectionError('At least one node has to be successfully added')

    def get_node(self, service_name):
        """Return the instance of SshNode class referenced by given service name."""
        try:
            return self.ssh_nodes[self.services[service_name]]
        except KeyError:
            exc_msg = f'"{service_name}" service not found/added. Use add_node method first.'
            raise ServiceNotFound(exc_msg)

    def delete_node(self, service_name):
        """Delete the instance of SshNode class referenced by given service name."""
        if service_name in self.services:
            hostname = self.services[service_name]
            del self.services[service_name]
            if hostname not in self.services.values():
                self.ssh_nodes[hostname].disconnect()
                del self.ssh_nodes[hostname]
            return True
        return False

    def get_was_node(self):
        was_services = next((s for s in self.services if s.endswith('was')), None)
        if was_services:
            return self.get_node(was_services)
        else:
            raise ServiceNotFound('No "was" node added')

    def clean_all(self):
        """Clean all configured data, i.e., web node, and all SSH nodes in use."""
        self.__init__()

    def _verify_node(self, service_name, ssh_connection):
        with ssh_connection as ssh:
            command = (f'{self.SCRIPT_PATH} status service {service_name} | '
                       f'grep $(hostname) | awk -F":" \'{{ print $3}}\'')
            status = ssh.execute_command(command).stdout
            if not status:
                command = (f'{self.SCRIPT_PATH} status node $(hostname) | '
                           f'grep -E "{"|".join(self.SUPPORTED_SERVICES)}" | '
                           'awk \'{{ print $1}}\' | sed "s/-$(hostname)//g"')
                services = ssh.execute_command(command).stdout
                exc_msg = (f'"{service_name}" service is not available on {ssh.hostname}.\n'
                           f'Available services (only supported by lib): {", ".join(services.splitlines())}')
                raise ServiceNotAvailable(exc_msg)
        if status != 'started':
            warn_msg = (f'"{service_name}" service status is "{status}", whilst expected is "started".\n'
                        f'In case of any issue please contact NetAct administrators first to clarify it.')
            logger.warning(warn_msg)

    def _ip_pattern(self, hostname):
        if re.search(self.IP_PATTERNS['ipv4'], hostname):
            return self.IP_PATTERNS['ipv4']
        elif re.search(self.IP_PATTERNS['ipv6'], hostname):
            return self.IP_PATTERNS['ipv6']
        else:
            raise ValueError(f'"{hostname}" hostname doesn\'t match IPv4 or IPv6 pattern')
